import Foundation

/// One catalogue calibre with its dimensions in millimetres and a side-view outline.
/// Generated by tools/generate_data.py into Resources/Cartridges.json.
struct Cartridge: Decodable, Identifiable, Hashable {
    let id: String
    let name: String
    /// German category name from the catalogue, see `CartridgeCatalog.Category`.
    let category: String
    /// rimless, rimmed, belted, rimfire, shot, ball, minie or pellet.
    let kind: String
    let aliases: [String]
    /// Printable alternative names, e.g. "9 mm Luger" for 9x19 mm.
    let displayAliases: [String]
    /// Spellings found on headstamps, e.g. "WIN 308", for the catalogue search.
    let headstamps: [String]
    /// No longer in regular factory production (only surplus, boutique loads or reloading).
    /// Matching skips these unless the «Veraltete Kaliber» switch is on.
    let obsolete: Bool
    /// A crimped blank (power-tool load, starter pistol blank): no bullet, the case is the whole cartridge.
    let blank: Bool
    let dimensions: Dimensions
    let outline: Outline
    /// Nil for rimfire and for balls, Minié bullets and pellets.
    let primer: Primer?

    /// The primer in the centre of the case head (Boxer size of commercial brass).
    struct Primer: Decodable, Hashable {
        /// small-pistol, large-pistol, small-rifle, large-rifle, shotshell-209 or bmg-35.
        let type: String
        /// Cup diameter in mm.
        let diameter: Double

        /// German title, used as localization key.
        var title: String {
            switch type {
            case "small-pistol": "Pistole klein"
            case "large-pistol": "Pistole gross"
            case "small-rifle": "Büchse klein"
            case "large-rifle": "Büchse gross"
            case "shotshell-209": "Schrot (209)"
            case "bmg-35": ".50 BMG (#35)"
            default: type
            }
        }
    }

    struct Dimensions: Decodable, Hashable {
        let rim: Double
        let base: Double
        /// Only for bottleneck cases.
        let shoulder: Double?
        let neck: Double
        /// 0 for round balls, Minié bullets and pellets (no case).
        let caseLength: Double
        let overallLength: Double
        let bullet: Double
    }

    /// Side view in millimetres: tip at y = 0, base at y = `height`, centred in `width`.
    struct Outline: Decodable, Hashable {
        let width: Double
        let height: Double
        let `case`: String?
        let head: String?
        let bullet: String?
        /// Paper band drawn over the bullet (paper-patched GP 1890 bullet); nil for jacketed bullets.
        /// Not part of the silhouette: `bullet` already covers it.
        let patch: String?
        /// "steel" for a steel-capped nose; nil means copper (or lead without a case).
        let bulletMaterial: String?
    }

    var hasCase: Bool { dimensions.caseLength > 0 }

    /// Diameter of the case head seen from below: the rim, or the base where it is wider.
    var headDiameter: Double { max(dimensions.rim, dimensions.base) }

    /// All names the cartridge is known by, for search.
    var allNames: [String] { [name] + displayAliases + aliases + headstamps }
}
